typedef struct {
    uint8_t *buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} ring_buffer_t;

int ring_buffer_init(ring_buffer_t *rb, uint8_t *storage, size_t capacity) {
    if (!rb || !storage || capacity == 0) return -1;
    rb->buffer = storage;
    rb->capacity = capacity;
    rb->head = rb->tail = rb->count = 0;
    if (pthread_mutex_init(&rb->lock, NULL) != 0) return -1;
    if (pthread_cond_init(&rb->not_empty, NULL) != 0) {
        pthread_mutex_destroy(&rb->lock);
        return -1;
    }
    if (pthread_cond_init(&rb->not_full, NULL) != 0) {
        pthread_cond_destroy(&rb->not_empty);
        pthread_mutex_destroy(&rb->lock);
        return -1;
    }
    return 0;
}

public sealed class EventPipeline<T>
{
    private readonly Channel<T> _channel;
    public EventPipeline(int capacity = 1024)
    {
        var options = new BoundedChannelOptions(capacity)
        {
            FullMode = BoundedChannelFullMode.Wait,
            SingleWriter = false,
            SingleReader = false
        };
        _channel = Channel.CreateBounded<T>(options);
    }
    public async ValueTask PublishAsync(T item, CancellationToken ct = default)
        => await _channel.Writer.WriteAsync(item, ct).ConfigureAwait(false);
    public async IAsyncEnumerable<T> StreamAsync([EnumeratorCancellation] CancellationToken ct = default)
    {
        while (await _channel.Reader.WaitToReadAsync(ct).ConfigureAwait(false))
        {
            while (_channel.Reader.TryRead(out var item))
                yield return item;
        }
    }
}

use std::sync::atomic::{AtomicUsize, Ordering};

pub struct SharedNode<T> {
    data: T,
    refs: AtomicUsize,
}

impl<T> SharedNode<T> {
    pub fn new(data: T) -> Self {
        Self { data, refs: AtomicUsize::new(1) }
    }
    pub fn acquire(&self) {
        self.refs.fetch_add(1, Ordering::Relaxed);
    }
    pub fn release(&self) -> bool {
        if self.refs.fetch_sub(1, Ordering::Release) == 1 {
            std::sync::atomic::fence(Ordering::Acquire);
            true // Last reference dropped; trigger deallocation
        } else {
            false
        }
    }
}

import java.util.concurrent.*;

public final class LoomWorkerPool {
    public static <T> List<T> executeAll(List<Callable<T>> tasks, Duration timeout) throws Exception {
        try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
            var subtasks = tasks.stream()
                .map(scope::fork)
                .toList();
            scope.joinUntil(Instant.now().plus(timeout));
            scope.throwIfFailed();
            return subtasks.stream().map(StructuredTaskScope.Subtask::get).toList();
        }
    }
}

type State =
  | { status: 'idle' }
  | { status: 'connecting'; host: string; attempts: number }
  | { status: 'connected'; socketId: string }
  | { status: 'failed'; error: Error };

type Action =
  | { type: 'CONNECT'; host: string }
  | { type: 'SUCCESS'; socketId: string }
  | { type: 'RETRY' }
  | { type: 'FAIL'; error: Error };

function transition(state: State, action: Action): State {
  switch (state.status) {
    case 'idle':
      return action.type === 'CONNECT'
        ? { status: 'connecting', host: action.host, attempts: 1 }
        : state;
    case 'connecting':
      if (action.type === 'SUCCESS') return { status: 'connected', socketId: action.socketId };
      if (action.type === 'RETRY') return { ...state, attempts: state.attempts + 1 };
      if (action.type === 'FAIL') return { status: 'failed', error: action.error };
      return state;
    case 'connected':
    case 'failed':
      return state;
    default:
      const _exhaustive: never = state;
      return _exhaustive;
  }
}

import http from 'node:http';

export function startSseServer(port = 8080) {
  const clients = new Set();
  const server = http.createServer((req, res) => {
    if (req.url === '/events') {
      res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache, no-store, no-transform',
        'Connection': 'keep-alive',
        'X-Accel-Buffering': 'no',
      });
      res.write(': ' + ' '.repeat(2048) + '\n\n'); // Flush reverse-proxy buffers
      clients.add(res);
      req.on('close', () => clients.delete(res));
    }
  });
  const ping = setInterval(() => {
    for (const res of clients) res.write(': ping\n\n');
  }, 15000);
  return server.listen(port);
}

require 'monitor'
require 'timeout'

class ConnectionPool
  include MonitorMixin

  def initialize(size: 5, timeout: 3.0, &factory)
    super()
    @size = size
    @timeout = timeout
    @factory = factory
    @available = []
    @cond = new_cond
    @size.times { @available << @factory.call }
  end

  def with_connection
    conn = nil
    synchronize do
      deadline = Process.clock_gettime(Process::CLOCK_MONOTONIC) + @timeout
      while @available.empty?
        remaining = deadline - Process.clock_gettime(Process::CLOCK_MONOTONIC)
        raise Timeout::Error, 'Pool connection timeout' if remaining <= 0
        @cond.wait(remaining)
      end
      conn = @available.pop
    end
    yield conn
  ensure
    synchronize do
      @available.push(conn) if conn
      @cond.signal
    end
  end
end
